def food(slot, slug, kw, plural, singular, short, title, meta, h1, answer, why, searches, lsa_name, gbp, services, signature, season, secondary, hero, links, schema="Restaurant", **over):
    d = (dict(
        slug=slug, query=kw.lower(), kw=kw, plural=plural, singular=singular, short=short,
        eyebrow="Local SEO · Food", title=title, meta=meta, h1=h1, answer=answer,
        takeaways=["Diners search nearby and hungry.", "A text menu helps search and AI.", "Photos of signature dishes sell.",
                   "Exact hours and ordering links matter.", "Reviews that name dishes help."],
        why=why, searches=searches,
        rank_note="Proximity matters for food searches, so a complete profile is key; relevance comes from a text menu and prominence from reviews and photos." + lsa(lsa_name),
        ai_note=f"AI assistants asked for the best {short} nearby tend to name places with clear menus, accurate hours and strong reviews that mention specific dishes.",
        gbp=gbp, services=services,
        area="Give your address, parking and nearby landmarks, and mention delivery areas and catering coverage across Orange County.",
        review_topics=["Dish ordered", "Taste", "Portion", "Service", "Atmosphere"],
        trust=f"Show your full menu with prices, {signature}, allergen and dietary information where you can, and real photos of your food and dining room. " + MENU,
        schema=schema,
        content=["Full menu page as text", "Signature dishes page", "Dietary and allergen guide",
                 "Catering and large orders", "Hours, parking and location page", "Online ordering and reservations page"],
        season=season,
        mistakes=["Menu only as a photo or PDF", "Wrong or missing holiday hours", "Old photos", "Ordering links to an old provider", "Ignoring reviews"],
        kpi="Orders, reservations and visits by source",
        short_version=f"{plural[0].upper() + plural[1:]} win with a text menu, photos of signature dishes, exact hours, working ordering links and reviews that name dishes.",
        faqs=[(f"How do {plural} get more customers?", "A text menu, signature dish photos, exact hours, ordering links and reviews."),
              (f"Should {plural} publish the menu online?", "Yes, as text with prices, on the website and listings."),
              (f"What schema fits a {singular}?", f"{schema} with menu, hours and location."),
              ("Do photos matter on Google and Apple Maps?", "Yes. Many diners choose by photos of dishes."),
              (f"Can {plural} use Local Services Ads?", f"Google lists {lsa_name} as an eligible category in the United States.")],
        score=[("Text menu", 5, "Relevance."), ("Dish photos", 5, "Choices."), ("Exact hours", 5, "Visits."),
               ("Reviews", 4, "Trust."), ("Photo-only menu", 2, "Missed searches.")],
        secondary=secondary, hero_query=hero, short_title=f"SEO for {short}",
        links=links))
    d.update(over)
    d.update(OVR.get(slug, {}))
    return industry(slot, d)


